class CalibrationNormalizer:
    """
    Frozen Block4.3 fit-only normalization.

    Calibration data never contributes
    normalization statistics.
    """

    def __init__(
        self,
        statistics,
        *,
        device,
    ):
        self.feature_mean = torch.tensor(
            statistics[
                "continuous_feature_mean"
            ],
            dtype=torch.float32,
            device=device,
        )

        self.feature_std = torch.tensor(
            statistics[
                "continuous_feature_std"
            ],
            dtype=torch.float32,
            device=device,
        )

        self.map_mean = torch.tensor(
            statistics[
                "map_mean"
            ],
            dtype=torch.float32,
            device=device,
        )

        self.map_std = torch.tensor(
            statistics[
                "map_std"
            ],
            dtype=torch.float32,
            device=device,
        )

        self.label_mean = torch.tensor(
            statistics[
                "label_displacement_mean"
            ],
            dtype=torch.float32,
            device=device,
        )

        self.label_std = torch.tensor(
            statistics[
                "label_displacement_std"
            ],
            dtype=torch.float32,
            device=device,
        )

        for name, value in (
            (
                "feature_std",
                self.feature_std,
            ),
            (
                "map_std",
                self.map_std,
            ),
            (
                "label_std",
                self.label_std,
            ),
        ):
            if bool(
                torch.any(
                    value <= 0.0
                )

def actor_class_id(
    actor_class: str,
) -> int:
    if actor_class == (
        "TYPE_VEHICLE"
    ):
        return CLASS_VEHICLE

    if actor_class == (
        "TYPE_PEDESTRIAN"
    ):
        return CLASS_PEDESTRIAN

    if actor_class == (
        "TYPE_CYCLIST"
    ):
        return CLASS_CYCLIST

    return CLASS_OTHER

