    scale_tril: torch.Tensor,
    variance_scale,
) -> torch.Tensor:
    """
    Apply alpha_h to predictive covariance by
    multiplying Cholesky factor by sqrt(alpha_h).
    """

    if scale_tril.ndim != 4:
        raise ValueError(
            "scale_tril must be "
            "[B,H,3,3]."
        )

    if scale_tril.shape[1:] != (
        HORIZON_COUNT,
        POSITION_DIM,
        POSITION_DIM,
    ):
        raise ValueError(
            "Predictive Cholesky "
            "shape changed."
        )

    scale = torch.as_tensor(
        variance_scale,
        dtype=scale_tril.dtype,
        device=scale_tril.device,
    )

    if scale.shape != (
        HORIZON_COUNT,
    ):
        raise ValueError(
            "variance_scale must "
            "have shape [4]."
        )

    if not bool(
        torch.isfinite(
            scale
        ).all()
    ):
        raise ValueError(
            "Variance scale contains "
            "non-finite values."
        )

    if bool(
        torch.any(
            scale
            <
            MIN_VARIANCE_SCALE
        )
    ):
        raise ValueError(
            "Variance scale below "
            "frozen lower bound."
        )

    if bool(
        torch.any(
            scale
