def masked_nll_metrics(
    nll,
    validity,
):
    value = np.asarray(
        nll,
        dtype=np.float64,
    )

    mask = (
        np.asarray(
            validity
        )
        >
        0.5
    )

    if value.shape != mask.shape:
        raise ValueError(
            "NLL/mask shape mismatch."
        )

    if (
        value.ndim != 2
        or
        value.shape[1] != 4
    ):
        raise ValueError(
            "Expected NLL [N,4]."
        )

    if not np.all(
        np.isfinite(
            value[
                mask
            ]
        )
    ):
        raise ValueError(
            "Valid NLL values "
            "must be finite."
        )

    horizon_names = (
        "0.1",
        "0.3",
        "0.5",
        "1.0",
